import sys, yaml, json
data = yaml.safe_load(sys.stdin)
# Find all DONE experiments that ran on westd-34685
done_on_34685 = {}
for exp_id, exp in data.get('experiments', {}).items():
    spec = exp.get('spec') or {}
    server = spec.get('server', '')
    if '34685' in str(server) and exp.get('status') == 'DONE':
        done_on_34685[exp_id] = {
            'conclusion': exp.get('conclusion'),
            'checkpoint_path': spec.get('checkpoint_path', ''),
            'log_path': spec.get('log_path', ''),
        }
print(json.dumps(done_on_34685, indent=2, default=str))
" 2>/dev/null | head -200

