import sys, yaml, json
data = yaml.safe_load(sys.stdin)
running = ['vanilla_v2_s1', 'vanilla_v2_s2', 'detach_ln_s3', 'cutoff_25k_s1_v2', 
           'reverse_cutoff_s2_v2', 'mvp_occ_s3_v2', 'full_occ_ln_s3_v2', 'ablation_occ_detach_s3_v2']
for eid in running:
    exp = data.get('experiments', {}).get(eid, {})
    missing = []
    if not exp.get('server'): missing.append('server')
    if not exp.get('gpu'): missing.append('gpu')
    if not exp.get('account'): missing.append('account')
    if not exp.get('pid'): missing.append('pid')
    spec = exp.get('spec') or {}
    if not spec.get('command'): missing.append('spec.command')
    if missing:
        print(f'{eid}: MISSING {missing}')
    else:
        print(f'{eid}: OK')
" 2>/dev/null
